    public function cargarDocumentos($param) {
        $conn =  Doctrine_Manager::connection();
        $sql = "SELECT 
                    det.iddocespaciotrabajo,
                    det.iddocumentogestor, 
                    det.nombrearchivo, 
                    det.descripcion,
                    det.extensionarchivo, 
                    det.idtipodocumento, 
                    et.idproceso,
                    det.iddocespaciotrabajo,
                    nom.dennomenclador
                  FROM 
                    mod_planificacion.dat_espaciotrabajo as et 
                    INNER JOIN mod_planificacion.dat_docespaciotrabajo as det
                    ON det.idespaciotrabajo = et.idespaciotrabajo
                    INNER JOIN mod_objetivos.nom_nomenclador as nom
                    ON det.idtipodocumento = nom.idnomenclador
                WHERE
                    et.idproceso = '{$param['idelemento']}' AND det.idtipodocumento = '{$param['iddocumentos']}' ";
                
        $datosListar = $conn->execute($sql);
        $datos = $datosListar->fetchAll(PDO::FETCH_ASSOC);
        return $datos;
    }
    
    public function SalvarDocumento($param, $iddocumentogestor) {
        $conn =  Doctrine_Manager::connection();
        $sql = "INSERT INTO mod_planificacion.dat_docespaciotrabajo(
                        idespaciotrabajo, iddocumentogestor, nombrearchivo, 
                        extensionarchivo, idtipodocumento, descripcion)
                VALUES ({$param['idespaciotrabajo']}, '{$iddocumentogestor[0]['id']}', '{$iddocumentogestor[0]['name']}', 
                        '{$param['extensionarchivo']}', '{$param['idtipodocumento']}', '{$param['descripcion']}');";
                
        $conn->execute($sql);
        return 1;
    }
    public function EliminarDocumento($param) {
        $conn =  Doctrine_Manager::connection();
        $sql = "DELETE FROM mod_planificacion.dat_docespaciotrabajo
                    WHERE dat_docespaciotrabajo.iddocespaciotrabajo = {$param['iddocespaciotrabajo']}";
                
        $conn->execute($sql);
        return 1;
    }

